//! Raw UTF-16 FORM named reads share exact matching and duplicate refusal.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<form id=form><input id=first name=one><input id=second name=two></form>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn raw_form_named_lookup_exact_live_id_name_native_override_and_prototype_fallback(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var form=document.getElementById('form'),x=document.getElementById('first'),other=document.getElementById('second'),P=HTMLFormElement.prototype,calls=0;Object.defineProperty(P,'A\ud800Z',{get:function(){calls++;return this;},configurable:true});if(form['A\ud800Z']!==form||calls!==1)throw 'prototype raw key';x.name='A\ud800Z';if(form['A\ud800Z']!==x||calls!==1||form['A\ufffdZ']!==undefined)throw 'native override exact';other.setAttributeNS(null,'id','B\udfff');if(form['B\udfff']!==other)throw 'raw ID';x.name='changed';if(form['A\ud800Z']!==form||calls!==2)throw 'live fallback';delete P['A\ud800Z'];if(form['A\ud800Z']!==undefined)throw 'deleted prototype';"#);}
#[test]
fn raw_form_named_duplicate_refusal_preserves_state_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var form=document.getElementById('form'),x=document.getElementById('first'),y=document.getElementById('second');x.name='A\ud800Z';y.name='A\ud800Z';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let error=p.runtime.execute(r#"form['A\ud800Z'];"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("RadioNodeList"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,r#"y.name='other';if(form['A\ud800Z']!==x)throw 'recovery';"#);}
#[test]
fn raw_form_named_work_deadline_refusal_and_borrowed_zero_copy_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('first');x.name='A\ud800Z';"#);let form=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let first=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("first")).unwrap();let units=[65,0xd800,90];let before=format!("{:?}",d.nodes);for expired in [false,true]{p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.named_units_property(node_handle(form),&units).unwrap_err();assert!(!error.is_empty());assert_eq!(format!("{:?}",d.nodes),before);p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(matches!(bridge.named_units_property(node_handle(form),&units).unwrap(),Some(Value::Host(h))if h==node_handle(first)));}}
